  Future<void> _load()async{if(mounted)setState((){_loading=true;_error=null;_guidance=null;});try{final relationships=await widget.apiClient.getCareRelationships();Map<String,dynamic>? summary;String? patientId,patientName;for(final relationship in relationships){if(relationship['status']?.toString().toLowerCase()!='active')continue;final candidate=relationship['patientUserId']?.toString();if(candidate==null||candidate.isEmpty)continue;try{final value=await widget.apiClient.getCareRecipientWomenCalendar(patientUserId:candidate);summary=value;patientId=candidate;patientName=relationship['patientDisplayName']?.toString();break;}on LifeMateApiException catch(error){if(error.code=='women_calendar_access_denied'||error.code=='women_calendar_not_active')continue;rethrow;}}
