    if(!mounted)return;setState((){_patientUserId=patientId;_patientName=patientName;_guidance=selected;_loading=false;});if(selected!=null){try{await _companionApi.recordImpression(patientUserId:patientId,guidanceId:selected.id,contentVersion:selected.contentVersion,category:selected.category);}on LifeMateApiException catch(error){if(error.code=='women_calendar_access_denied'&&mounted)setState((){_guidance=null;_error='locked';});}}
  }catch(error){if(!mounted)return;setState((){_loading=false;_error=error.toString();});}}

